UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Pilates'), description_de = COALESCE(description_de, 'Stärkt die Rückenmuskulatur. Die Trainerin oder der Trainer sollte über die Schwangerschaft informiert sein.') WHERE id = 'a9929822-3bb0-4d7c-a4c2-2a4b33e92a3e';
