UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Heißes Bad / Sauna'), description_de = COALESCE(description_de, 'Ein Anstieg der Körpertemperatur auf über 39°C ist für den Fötus gefährlich. Eine lauwarme Dusche ist in Ordnung.') WHERE id = 'ac0aee5f-a79c-4c84-b5d8-ef03a487b436';
