UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Schokolade'), description_de = COALESCE(description_de, 'Kann in kleinen Mengen gegessen werden. Achte dabei auf den Koffein- und Zuckergehalt.') WHERE id = 'b4392c92-b356-4f01-8438-8c0f357714ef';
