UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Pflaume'), description_de = COALESCE(description_de, 'Ist unbedenklich und fördert die Verdauung.') WHERE id = 'b48ef54c-3301-4c72-9e1d-015b47bf0be0';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Thunfisch (Konserve)'), description_de = COALESCE(description_de, 'Bis zu 140 Gramm pro Woche sind erlaubt (Quecksilberrisiko).') WHERE id = 'b5136762-1228-4319-a02d-71a442045140';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Feigenkonfitüre'), description_de = COALESCE(description_de, 'Fördert die Verdauung.') WHERE id = 'b62f0f82-1af4-4811-910c-583d477987e7';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Bulgur'), description_de = COALESCE(description_de, 'Enthält mehr Ballaststoffe als Reis und ist gesund.') WHERE id = 'b728c753-908a-4c9b-be3a-95f134405968';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Himbeerblättertee'), description_de = COALESCE(description_de, 'Nur gegen Ende des 3. Trimesters (ab der 36. Woche) zur Geburtsvorbereitung erlaubt.') WHERE id = 'b73d6256-1d85-4003-b933-0538a317f86f';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Sport (leicht)'), description_de = COALESCE(description_de, 'Spazierengehen, Schwimmen und Schwangerschaftsyoga sind empfehlenswert.') WHERE id = 'b7a6fc30-872d-4080-ab2a-e4fa0f992f45';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Zucker / Süßigkeiten'), description_de = COALESCE(description_de, 'Bei einem erhöhten Risiko für Schwangerschaftsdiabetes ist eine strenge Kontrolle erforderlich.') WHERE id = 'b89c53eb-32bc-412b-9682-ea88d2687297';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Roller fahren'), description_de = COALESCE(description_de, 'Beim Rollerfahren besteht Sturz- und Verletzungsgefahr, was während der Schwangerschaft gefährlich sein kann. Verzichte am besten darauf.') WHERE id = 'c12e6733-ed2c-48df-9554-d169b3d3df30';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Wimpernlifting'), description_de = COALESCE(description_de, 'Die chemischen Substanzen können ins Auge gelangen. Ein Allergietest ist unbedingt erforderlich.') WHERE id = 'c1ad91ac-a9d7-4f8b-be51-bcfc572993be';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Kakao'), description_de = COALESCE(description_de, 'In kleinen Mengen erlaubt. Enthält Koffein.') WHERE id = 'c2eda676-4afc-47fd-8f07-97d50bd55942';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Hijama (blutiges Schröpfen)'), description_de = COALESCE(description_de, 'Es besteht die Gefahr von Blutverlust und Infektionen. Außerdem kann der Blutdruck abfallen.') WHERE id = 'ad945485-a623-4a91-afca-c9d7bba8b9c8';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Joghurt / Kefir'), description_de = COALESCE(description_de, 'Eine gute Quelle für Kalzium und Probiotika.') WHERE id = 'ada1521c-d651-4273-b3da-e1874aaf6625';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Flugreisen'), description_de = COALESCE(description_de, 'Flüge mit kommerziellen Fluggesellschaften gelten während der Schwangerschaft im Allgemeinen als sicher. Dennoch solltest du dich insbesondere vor Langstreckenflügen ärztlich beraten lassen, auch wenn keine Schwangerschaftskomplikationen vorliegen. Trinke ausreichend Wasser, bewege dich regelmäßig, um Blutgerinnseln vorzubeugen, und trage Kompressionsstrümpfe, falls diese empfohlen werden. Diese Empfehlungen gelten auch für stillende Mütter. Bei langen Flügen kann es jedoch hilfreich sein, zusätzliche Vorkehrungen für das Füttern und Wohlbefinden des Babys zu treffen.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Lachs'), description_de = COALESCE(description_de, 'Eine gute Quelle für Omega-3-Fettsäuren. Bis zu zweimal pro Woche wird vollständig durchgegarter Lachs empfohlen.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Fliegen'), description_de = COALESCE(description_de, 'Kommerzielle Flüge gelten während der Schwangerschaft im Allgemeinen als sicher. Es wird empfohlen, dich insbesondere im dritten Trimester ärztlich zum Fliegen beraten zu lassen. Trinke ausreichend Wasser und bewege dich regelmäßig, um Blutgerinnseln vorzubeugen. Diese Empfehlungen gelten auch für stillende Mütter. Bei langen Flügen solltest du jedoch zusätzliche Vorkehrungen für das Füttern und Wohlbefinden des Babys treffen.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Sucuk'), description_de = COALESCE(description_de, 'Sucuk ist während der Stillzeit in Maßen im Allgemeinen unbedenklich. Allerdings solltest du den hohen Salz- und Fettgehalt berücksichtigen. Scharf gewürzte Lebensmittel können sich zudem manchmal über die Muttermilch auf das Baby auswirken und Unwohlsein oder Verdauungsprobleme verursachen. Beobachte, wie dein Baby darauf reagiert.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Laufen (Running)'), description_de = COALESCE(description_de, 'Wenn du schon vor der Schwangerschaft gelaufen bist, kannst du damit weitermachen – allerdings in geringerem Tempo. Während der Schwangerschaft solltest du nicht neu damit beginnen.') WHERE id = '92962cf9-e5ec-49cb-81b4-c102843ffd96';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Papaverin (Zäpfchen)'), description_de = COALESCE(description_de, 'Wird bei erhöhtem Gebärmuttertonus angewendet. Nur nach ärztlicher Verordnung.') WHERE id = '92a311a8-2353-49f2-a478-69bbb6e11521';
