UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Zelyonka (Brillantgrün)'), description_de = COALESCE(description_de, 'Die äußerliche Anwendung, zum Beispiel auf einer Wunde, ist unbedenklich.') WHERE id = '92d5127f-93c5-475a-8efe-d203d95f8692';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Kompressionsstrümpfe'), description_de = COALESCE(description_de, 'Beugen Krampfadern vor und lindern Schwellungen.') WHERE id = '936379c9-7b34-4707-87a4-0cb406f01a7e';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Ananas'), description_de = COALESCE(description_de, 'Mythos: Um Wehen auszulösen, müsste man 7-8 ganze Ananas essen. In normalen Mengen ist Ananas unbedenklich.') WHERE id = '9465bd4b-eaf1-49d5-b708-d311399b2d80';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Gelee'), description_de = COALESCE(description_de, 'Gelatine ist unbedenklich.') WHERE id = 'c3158731-b3af-4f97-ae42-ad2765f8836f';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Wasserpfeife'), description_de = COALESCE(description_de, 'Enthält mehr Kohlenmonoxid und Giftstoffe als Zigaretten.') WHERE id = 'c441fedf-30cd-4df7-aeb7-6c6d4c83ce37';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Düşbərə'), description_de = COALESCE(description_de, 'Ist unbedenklich, aber achte wegen möglichem Sodbrennen auf die Menge an Pfeffer.') WHERE id = 'c61ac58a-22c8-4dd1-80b5-b2984f6468bc';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Avocado'), description_de = COALESCE(description_de, 'Ist reich an Folsäure und sehr gesund.') WHERE id = 'c92870c6-4067-413f-bf1f-9c3c54c225ff';
UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Schwarzer Tee'), description_de = COALESCE(description_de, 'Enthält Koffein; mehr als 3-4 Tassen täglich werden nicht empfohlen. Trinke ihn nicht gleichzeitig mit Eisenpräparaten.') WHERE id = 'ca2a1163-b2b3-49fd-96d1-10ea4d670bb2';
