UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Surfen'), description_de = COALESCE(description_de, 'Beim Surfen besteht ein hohes Risiko für Stürze, Zusammenstöße und Verletzungen durch das Surfbrett oder den Aufprall auf das Wasser. Dies kann für Schwangere gefährlich sein. Daher wird Surfen während der Schwangerschaft grundsätzlich nicht empfohlen, insbesondere im weiteren Verlauf, wenn sich der Gleichgewichtssinn verändert.') WHERE id = 'd73743e4-7872-43bc-9d17-1a2b6c256ae0';
