UPDATE public.safety_items SET name_de = COALESCE(name_de, 'Zwiebel'), description_de = COALESCE(description_de, 'Unbedenklich.') WHERE id = 'db0ccc2f-9c44-49a3-a91f-95b0501ebf1f';
