UPDATE public.teething_care_tips SET title_de = COALESCE(title_de, 'Zucker vermeiden'), content_de = COALESCE(content_de, 'Vermeide zuckerhaltige Speisen und Getränke, insbesondere vor dem Schlafengehen, um frühkindlicher Karies vorzubeugen.') WHERE id = '5c0c2cd7-bbc3-4acf-aa29-a75ff9325110';
