UPDATE public.teething_care_tips SET title_de = COALESCE(title_de, 'Gekühlte Beißringe'), content_de = COALESCE(content_de, 'Bewahre Beißringe im Kühlschrank auf. Friere sie niemals ein, da sie sonst für das Zahnfleisch deines Babys zu kalt sein können.') WHERE id = '6e21f5d7-f642-4d33-9bfc-bd32e68b561c';
